import type { Dua, DuaPart } from '../../types';

// Cevşen-i Kebir (Dua-i Cevşen Kebir) — 100 bölüm.
// Arapça metin: duas.org (mobil sayfa) üzerinden okunarak alınmıştır; her bölümün sonundaki ortak nakarat (SUBHANEKE) sabit tutulup birleştirilir.
// Türkçe okunuş, Arapça harekeli metinden kural tabanlı türetilmiştir; anlam (meal) özgün cümlelerle yazılmıştır.

const SUBHANEKE_AR = "سُبْحَانَكَ يَا لا إلَهَ إلاّ أنْتَ\nالغَوْثَ الغَوْثَ\nخَلِّصْنا مِنَ النّارِ يا رَبِّ";
const SUBHANEKE_OKUNUS = "Sübhâneke yâ lâ ilâhe illâ ente\nel-gavs el-gavs\nhallisnâ mine'n-nâr yâ Rabb";
const SUBHANEKE_MEAL = "Seni tesbih ederim; Senden başka ilâh yoktur.\nİmdat, imdat!\nBizi ateşten kurtar, ey Rabbimiz.";

type Raw = [ar: string[], okunus: string[], meal: string[]];

const bolum = (n: number, [ar, okunus, meal]: Raw): DuaPart => ({
  heading: `Bölüm ${n}`,
  ar: [...ar, SUBHANEKE_AR].join("\n"),
  okunus: [...okunus, SUBHANEKE_OKUNUS].join("\n"),
  meal: [...meal, SUBHANEKE_MEAL].join("\n"),
});

